// Keep the last successfully loaded A/B pair in this browser, without sending it to a service.
let lastPatternDb, lastPatternPair=null, restoringLastPatterns=false;
function openLastPatternDb(){
  if(!lastPatternDb)lastPatternDb=new Promise((resolve,reject)=>{
    if(typeof indexedDB==='undefined')return reject(Error('浏览器不支持本地保存'));
    const request=indexedDB.open('zhijing-last-patterns',1);
    request.onupgradeneeded=()=>request.result.createObjectStore('patterns');
    request.onsuccess=()=>resolve(request.result);
    request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('本地花型库暂不可用'));
  });
  return lastPatternDb;
}
async function lastPatternStorage(mode,value){
  const db=await openLastPatternDb();
  return new Promise((resolve,reject)=>{
    const transaction=db.transaction('patterns',mode),store=transaction.objectStore('patterns');
    const request=mode==='readonly'?store.get('last-pair'):store.put(value,'last-pair');
    transaction.oncomplete=()=>resolve(request.result);
    transaction.onerror=()=>reject(transaction.error||request.error);
    transaction.onabort=()=>reject(transaction.error||Error('花型保存未完成'));
  });
}
function validSavedPattern(item){return !!item&&item.blob instanceof Blob&&['image/png','image/jpeg','image/webp'].includes(item.blob.type)&&item.blob.size>0&&item.blob.size<=10*1024*1024;}
function refreshLastPatternButton(){const button=$('restoreLastPatterns');if(!button)return;button.disabled=!lastPatternPair||state.busy||restoringLastPatterns;button.textContent=restoringLastPatterns?'正在填入…':'使用上次花型';button.title=lastPatternPair?(lastPatternPair.b?'一键填入上次的 A/B 面花型':'填入上次 A 面花型，B 面留空'):'上传花型后，会自动保存在当前浏览器';}
async function rememberLastPatterns(){
  if(restoringLastPatterns||!state.upload)return;
  const pack=file=>({blob:file,name:file.name,lastModified:file.lastModified});
  const pair={a:pack(state.upload.file),b:state.uploadB?pack(state.uploadB.file):null,materials:globalThis.patternMaterials?.storage()};
  lastPatternPair=pair;refreshLastPatternButton();
  try{await lastPatternStorage('readwrite',pair);}catch{toast('花型已加载，但浏览器未能保存；关闭页面后需重新上传');}
}
async function restoreLastPatterns(){
  if(state.busy)return toast('请等待当前生成完成');
  if(restoringLastPatterns||!lastPatternPair)return;
  const pair=lastPatternPair;restoringLastPatterns=true;refreshLastPatternButton();
  const unpack=item=>new File([item.blob],item.name||'面料花型.png',{type:item.blob.type,lastModified:item.lastModified||Date.now()});
  try{
    // Validate both panels before replacing either; a broken saved pair leaves the current uploads intact.
    for(const item of [pair.a,pair.b].filter(Boolean)){
      if(!validSavedPattern(item))throw Error('上次花型无法读取，请重新上传');
      const url=URL.createObjectURL(item.blob);
      try{const image=new Image();image.src=url;await image.decode();if(image.naturalWidth>16000||image.naturalHeight>16000)throw Error('上次花型尺寸超出限制');}finally{URL.revokeObjectURL(url);}
    }
    await upload(unpack(pair.a));
    if(pair.b)await uploadBack(unpack(pair.b));
    else $('removeUploadB').onclick();
    await globalThis.patternMaterials?.restore(pair.materials);
    toast(pair.b?'已填入上次 A/B 面花型':'已填入上次 A 面花型');
  }catch(error){toast(error.message||'上次花型无法读取，请重新上传');}
  finally{restoringLastPatterns=false;refreshLastPatternButton();}
}
async function loadLastPatterns(){
  try{const pair=await lastPatternStorage('readonly');if(!lastPatternPair&&validSavedPattern(pair?.a)&&(!pair.b||validSavedPattern(pair.b)))lastPatternPair=pair;}catch{}
  refreshLastPatternButton();
}
