function makePattern(index){const c=document.createElement('canvas');c.width=c.height=240;const x=c.getContext('2d');const palettes=[['#eeeee1','#839378'],['#f1e8df','#b9867d'],['#ece7d4','#a4a887'],['#f1eee6','#6e8192']];const [bg,ink]=palettes[index];x.fillStyle=bg;x.fillRect(0,0,240,240);if(index===0){for(const [px,py,r] of [[60,62,-.35],[177,175,.4]]){x.save();x.translate(px,py);x.rotate(r);x.strokeStyle=ink;x.lineWidth=1.5;x.beginPath();x.moveTo(0,40);x.quadraticCurveTo(7,0,0,-45);x.stroke();for(let i=-3;i<=3;i++){x.save();x.translate(3,i*11);x.rotate(i%2===0?-.8:.8);x.fillStyle=ink;x.beginPath();x.ellipse(i%2===0?8:-8,0,11,4,0,0,Math.PI*2);x.fill();x.restore()}x.restore()}}else if(index===1){for(const [px,py] of [[58,60],[175,180]]){x.fillStyle=ink;for(let a=0;a<6;a++){x.beginPath();x.ellipse(px+Math.cos(a)*12,py+Math.sin(a)*12,9,13,a,0,Math.PI*2);x.fill()}x.fillStyle='#c9af6e';x.beginPath();x.arc(px,py,6,0,Math.PI*2);x.fill();x.strokeStyle='#9da08a';x.beginPath();x.moveTo(px,py+20);x.lineTo(px-8,py+65);x.stroke()}}else if(index===2){x.strokeStyle=ink;x.lineWidth=16;for(let i=-240;i<480;i+=45){x.beginPath();x.moveTo(i,0);x.lineTo(i+100,240);x.stroke()}x.globalAlpha=.2;x.strokeStyle='#fff';for(let i=0;i<240;i+=8){x.beginPath();x.moveTo(0,i);x.lineTo(240,i);x.stroke()}}else{x.fillStyle=ink;for(let i=0;i<6;i++)for(let j=0;j<6;j++){x.globalAlpha=(i+j)%2?.35:.6;x.beginPath();x.arc(i*44+15,j*44+15,3,0,7);x.fill()}}return c}
