function openImageViewer(items,index){items=(items||[]).filter(Boolean);if(!items.length)return;let i=Math.max(0,Math.min(index||0,items.length-1));const zoomLevels=[100,150,225,340];let zoomIdx=0;const step=direction=>{i=(i+direction+items.length)%items.length;paint()};function paint(){const item=items[i],img=$('modalContent').querySelector('.large-preview');if(!img)return;const label=item.title||'图片放大';img.src=item.src();img.alt=label;zoomIdx=0;img.classList.remove('zoomed');img.style.width='';img.style.height='';const sc=$('modalContent').querySelector('.preview-scroll');if(sc){sc.classList.remove('zoomed');sc.scrollLeft=0;sc.scrollTop=0}const heading=$('modalContent').querySelector('h2'),counter=$('modalContent').querySelector('.viewer-counter');if(heading)heading.textContent=label;if(counter)counter.textContent=(i+1)+' / '+items.length}modal('<h2></h2><div class="large-viewer"><button type="button" class="viewer-arrow viewer-prev" data-viewer="-1" aria-label="上一张"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m14 5-7 7 7 7" stroke-linecap="round" stroke-linejoin="round"/></svg></button><div class="preview-scroll"><img class="large-preview" alt="图片放大"></div><button type="button" class="viewer-arrow viewer-next" data-viewer="1" aria-label="下一张"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m10 5 7 7-7 7" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div><p class="viewer-counter"></p>');for(const button of $('modalContent').querySelectorAll('.viewer-arrow'))button.hidden=items.length<2;if(items.length<2)$('modalContent').querySelector('.viewer-counter').hidden=true;$('modalContent').querySelector('.viewer-prev').onclick=()=>step(-1);$('modalContent').querySelector('.viewer-next').onclick=()=>step(1);const preview=$('modalContent').querySelector('.large-preview'),scroller=$('modalContent').querySelector('.preview-scroll');let dragMoved=false,drag=null;preview.onclick=()=>{if(dragMoved){dragMoved=false;return}zoomIdx=(zoomIdx+1)%zoomLevels.length;const factor=zoomLevels[zoomIdx];preview.style.width=factor+'%';preview.style.height='auto';preview.classList.toggle('zoomed',factor>100);scroller.classList.toggle('zoomed',factor>100)};preview.addEventListener('mousedown',e=>{if(e.button!==0||!preview.classList.contains('zoomed'))return;drag={x:e.clientX,y:e.clientY,left:scroller.scrollLeft,top:scroller.scrollTop};dragMoved=false;e.preventDefault()});preview.addEventListener('mousemove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>3)dragMoved=true;scroller.scrollLeft=drag.left-dx;scroller.scrollTop=drag.top-dy});const endDrag=()=>{drag=null};preview.addEventListener('mouseup',endDrag);preview.addEventListener('mouseleave',endDrag);viewerKeys={prev:()=>step(-1),next:()=>step(1)};paint()}
