function matSurface(ctx,points,opt,print=true){
  const tile=document.createElement('canvas');tile.width=900;tile.height=1000;const t=tile.getContext('2d');
  const bamboo=opt.fabric==='bamboo',rattan=opt.fabric==='rattan';
  t.fillStyle=bamboo?'#cdb580':rattan?'#c5b18a':'#e9e4d5';t.fillRect(0,0,900,1000);
  if(print){const src=opt.surfaceB&&state.patternB?state.patternB:state.pattern||patterns[state.sample];const unit=140*opt.scale/100;const swatch=document.createElement('canvas');swatch.width=swatch.height=unit;const sx=swatch.getContext('2d');sx.translate(unit/2,unit/2);sx.rotate(opt.direction*Math.PI/180);sx.drawImage(src,-unit/2,-unit/2,unit,unit);t.globalAlpha=bamboo||rattan?.32:1;if(opt.repeat==='single')t.drawImage(src,0,0,900,1000);else{t.fillStyle=t.createPattern(swatch,'repeat');t.fillRect(0,0,900,1000)}t.globalAlpha=1;}
  if(bamboo){for(let y=0;y<1000;y+=20){const g=t.createLinearGradient(0,y,0,y+20);g.addColorStop(0,'#68523455');g.addColorStop(.2,'#fff5c235');g.addColorStop(1,'#98784525');t.fillStyle=g;t.fillRect(0,y,900,20);t.strokeStyle='#74603865';t.beginPath();t.moveTo(0,y);t.lineTo(900,y);t.stroke()}t.strokeStyle='#927d58';t.lineWidth=3;for(let x=90;x<900;x+=180){t.beginPath();t.moveTo(x,0);t.lineTo(x,1000);t.stroke()}}
  else {t.strokeStyle=rattan?'#776b4550':'#777b6c22';t.lineWidth=rattan?2:1;for(let y=0;y<1000;y+=rattan?8:3){t.beginPath();t.moveTo(0,y);t.lineTo(900,y);t.stroke()}for(let x=0;x<900;x+=rattan?10:4){t.beginPath();t.moveTo(x,0);t.lineTo(x,1000);t.stroke()}}
  // Map the complete flat woven surface to the product plane, preserving coherent perspective.
  const [a,b,c,d]=points;ctx.save();path(ctx,points);ctx.clip();
  for(let row=0;row<1000;row++){const v=row/1000,lx=a[0]+(d[0]-a[0])*v,ly=a[1]+(d[1]-a[1])*v,rx=b[0]+(c[0]-b[0])*v,ry=b[1]+(c[1]-b[1])*v;ctx.save();ctx.transform((rx-lx)/900,(ry-ly)/900,(d[0]-a[0])/1000,(d[1]-a[1])/1000,lx,ly);ctx.drawImage(tile,0,row,900,1,0,0,900,1.5);ctx.restore()}
  ctx.restore();path(ctx,points);ctx.lineJoin='round';ctx.lineWidth=print?10:6;ctx.strokeStyle=bamboo?'#9f8353':rattan?'#9c8664':'#aca78a';ctx.stroke();ctx.save();path(ctx,points);ctx.clip();ctx.setLineDash([3,5]);ctx.lineWidth=2;ctx.strokeStyle='#efebd2';ctx.stroke();ctx.restore();ctx.setLineDash([]);
}
