  const palette={warm:['#e7e1d4','#c6b395'],natural:['#dce2d4','#b99771'],hotel:['#7d7669','#645644'],studio:['#f1f1ed','#dbd9cc']}[scene]||['#e7e1d4','#c6b395'];
  x.fillStyle=palette[0];x.fillRect(0,0,1200,900);x.fillStyle=palette[1];x.fillRect(0,610,1200,290);
  if(scene!=='studio'){x.fillStyle='#f7f5e9';x.fillRect(945,75,190,440);x.strokeStyle='#bab49e';x.lineWidth=8;x.strokeRect(945,75,190,440);x.beginPath();x.moveTo(1040,75);x.lineTo(1040,515);x.stroke();x.fillStyle='#ffffff55';x.fillRect(914,45,28,505);x.fillStyle=palette[1];x.fillRect(90,516,120,110);x.fillStyle='#e8e0c8';x.beginPath();x.moveTo(95,425);x.lineTo(118,365);x.lineTo(174,365);x.lineTo(192,425);x.fill();x.fillRect(140,425,6,90)}
