// long before this line executes. A let here is still in its TDZ and would throw ReferenceError on load.
var lastShootingPlan=null;
function normalizeShootingPlan(plan){
  if(!plan||!Array.isArray(plan.scenes)||!Array.isArray(plan.angles))return null;
  const pickedScenes=[...new Set(plan.scenes)].filter(id=>scenes.some(s=>s.id===id));
  const pickedAngles=[...new Set(plan.angles)].filter(id=>angles.some(a=>a.id===id));
  return pickedScenes.length&&pickedAngles.length?{scenes:pickedScenes,angles:pickedAngles,savedAt:Number(plan.savedAt)||0}:null;
}
function readShootingPlan(){try{return normalizeShootingPlan(JSON.parse(localStorage.getItem(SHOOTING_PLAN_KEY)));}catch{return null;}}
function refreshApplyLastButton(){
  const button=$('applyLastShooting');if(!button)return;
  const plan=lastShootingPlan,locked=!!state.referenceUpload&&state.referenceScene!==false&&state.referenceAngle!==false;
  button.disabled=!plan||state.busy||locked;
  button.classList.toggle('has-history',!!plan);
  button.textContent='应用上次';
  button.title=locked?'参考图已接管场景与角度':plan?'回到上次：'+plan.scenes.length+' 个场景 · '+plan.angles.length+' 个角度':'生成一次后，可一键回到上次的场景与角度';
}
function rememberShootingPlan(){
  const plan=normalizeShootingPlan({scenes:state.scenes,angles:state.angles,savedAt:Date.now()});
  if(!plan)return;
  lastShootingPlan=plan;
  try{localStorage.setItem(SHOOTING_PLAN_KEY,JSON.stringify(plan));}catch{}
  refreshApplyLastButton();
}
function applyLastShootingPlan(){
  if(state.busy)return toast('请等待当前生成完成');
  const plan=lastShootingPlan;
  if(!plan)return toast('还没有上次的拍摄方案，先生成一次再试');
  const sceneLocked=!!state.referenceUpload&&state.referenceScene!==false,angleLocked=!!state.referenceUpload&&state.referenceAngle!==false;
  if(sceneLocked&&angleLocked)return toast('参考图已接管场景与角度，无需应用');
  if(!sceneLocked)state.scenes=[...plan.scenes];
  if(!angleLocked)state.angles=[...plan.angles];
  renderSelections();
  const button=$('applyLastShooting');
  if(button){button.classList.remove('applied');setTimeout(()=>button.classList.add('applied'),30);}
  toast('已应用上次：'+plan.scenes.length+' 个场景 · '+plan.angles.length+' 个角度');
}
$('applyLastShooting').onclick=applyLastShootingPlan;
lastShootingPlan=readShootingPlan();
refreshApplyLastButton();
// SHOOTING_PLAN_CACHE_END

let galleryClock=null,galleryPreviousLabels=null,galleryStartedAt=null;
function updateGalleryElapsed(finished=false){if(state.queueDisplay){$('jobBanner').hidden=true;$('jobElapsed').hidden=true;updateGenerationTaskTimes();return;}if(galleryStartedAt===null)return;const elapsed=$('jobElapsed'),seconds=Math.max(0,Math.floor((Date.now()-galleryStartedAt)/1000));if(finished)document.querySelector('.gallery-title-summary')?.append(elapsed);else{const details=$('jobMessage').querySelector('.job-message-details');if(details)details.append(elapsed);else $('jobMessage').after(elapsed);}elapsed.hidden=false;elapsed.textContent=(finished?'耗时 ':'已用时 ')+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
function setConfigCollapsed(collapsed){
  $('creationPanel').classList.toggle('is-collapsed',collapsed);
  $('toggleConfig').setAttribute('aria-expanded',String(!collapsed));
  $('toggleConfig').textContent=collapsed?'展开设置 ↓':'收起设置 ↑';
  $('configSummary').hidden=!collapsed;
  $('configSummary').textContent=(state.product==='pillowcore'&&typeof currentPillowcoreVariant==='function'?'枕芯 · '+currentPillowcoreVariant().name:state.product==='set'&&typeof currentSetVariant==='function'?currentSetVariant().name:state.product==='sheet'&&typeof currentSheetProductVariant==='function'?currentSheetProductVariant().name:state.product==='quilt'?'被芯 · '+(state.quiltSeason==='summer'?'夏凉被':'冬被'):state.product==='mattress'&&typeof currentMattressVariant==='function'?'床垫 · '+currentMattressVariant().name:state.product==='sleepbag'&&typeof currentSleepbagVariant==='function'?'更多产品 · '+currentSleepbagVariant().name:products.find(p=>p.id===state.product).name)+' · '+(state.textureSource==='upload'?'自上传质感':state.fabricMode==='selected'?fabrics[state.fabric][0]:'质感参考上传图')+' · '+(state.referenceUpload?referencePlanDescription(options()):state.scenes.length+' 个场景 · '+state.angles.length+' 个角度');
}
function beginGalleryGeneration(opt,isAI){
  state.queueDisplay=!!isAI;
  state.galleryRevision=(state.galleryRevision||0)+1;
  state.results=[];state.selected=0;state.galleryPicked=false;renderResults();
  globalThis.updateGalleryImageLayout?.({ratio:opt.ratio});
  globalThis.showCurrentGeneration?.();
  galleryStartedAt=Date.now();
  $('results').classList.add('is-generating');
  $('cancelBtn').hidden=false;
  $('results').classList.add('awaiting-first');
  galleryPreviousLabels=[$('resultTitle').textContent,$('resultSubtitle').textContent,$('resultKind').textContent];
  $('resultTitle').textContent='正在创作你的产品图片';
  $('resultSubtitle').textContent=(opt.recommendScene||opt.recommendAngle)?'系统推荐 · '+(opt.recommendScene?'推荐场景':'自选场景')+' + '+(opt.recommendAngle?'智能角度':'自选角度')+' · '+(opt.recommendCount*(opt.recommendScene?1:opt.scenes.length))+' 张':opt.referenceGuided?referencePlanDescription(opt):opt.scenes.length+' 个场景 × '+opt.angles.length+' 个角度，完成后逐张呈现';
  $('resultKind').textContent='生成中';
  $('galleryCount').textContent='0 / '+((opt.recommendScene||opt.recommendAngle)?opt.recommendCount*(opt.recommendScene?1:opt.scenes.length):opt.scenes.length*opt.angles.length)+' 张';
  $('loadingCount').textContent='已完成 0 / '+((opt.recommendScene||opt.recommendAngle)?opt.recommendCount*(opt.recommendScene?1:opt.scenes.length):opt.scenes.length*opt.angles.length)+' 张';
  $('loadingDetail').textContent='正在提交花型与拍摄要求…';
  updateGalleryElapsed();
  clearInterval(galleryClock);
  galleryClock=setInterval(()=>updateGalleryElapsed(),1000);
  if(isAI){requestAnimationFrame(()=>$('results').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));}
}
function endGalleryGeneration(){clearInterval(galleryClock);galleryClock=null;updateGalleryElapsed(true);$('cancelBtn').hidden=true;if(!$('jobBanner').classList.contains('error'))$('jobBanner').hidden=true;$('results').classList.remove('is-generating');if($('results').classList.contains('awaiting-first')){$('resultTitle').textContent='本次未生成图片';$('resultSubtitle').textContent='历史作品可在生成记录中查看';$('resultKind').textContent='';$('results').classList.remove('awaiting-first');selectResult(state.selected)}}
$('toggleConfig').onclick=()=>{const collapse=!$('creationPanel').classList.contains('is-collapsed');setConfigCollapsed(collapse);if(collapse)requestAnimationFrame(()=>{const anchor=document.querySelector('.workspace-grid')||$('creationPanel');anchor.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});};
$('previousImage').onclick=()=>{if(state.selected>0)selectResult(state.selected-1)};
$('nextImage').onclick=()=>{if(state.selected<state.results.length-1)selectResult(state.selected+1)};

// Size the gallery from the selected image, never from a fixed landscape frame.
(()=>{
  const layout=document.querySelector('.gallery-layout'),main=document.querySelector('.gallery-main'),frame=document.querySelector('.gallery-main .hero-frame'),image=document.getElementById('heroImage');
  if(!layout||!main||!frame)return;
  function requestedRatio(value){const parts=String(value||'').split(':').map(Number);return parts.length===2&&parts.every(n=>Number.isFinite(n)&&n>0)?parts[0]/parts[1]:1;}
  function update(result){
    if(!result)return;
    const source=result.canvas;
    let ratio=source?.width>0&&source?.height>0?source.width/source.height:requestedRatio(result.ratio);
    if(result.reference&&image?.naturalWidth>0&&image?.naturalHeight>0&&image.getAttribute('src')===(result.asset||'/assets/bedding-scenes.png'))ratio=image.naturalWidth/image.naturalHeight;
    if(!Number.isFinite(ratio)||ratio<=0)ratio=1;
    frame.style.aspectRatio=String(ratio);
    frame.style.height='auto';
    layout.style.setProperty('--gallery-main-column',Math.max(1,Math.min(2.1,ratio*1.5)).toFixed(3)+'fr');
    layout.style.setProperty('--gallery-frame-ratio',String(ratio));
    layout.dataset.imageShape=ratio>1.05?'landscape':ratio<.95?'portrait':'square';
  }
  // The header, thumbnails and editor share the height of the actual main card.
  function syncHeight(){const height=main.getBoundingClientRect().height;if(height>0)layout.style.setProperty('--gallery-browser-height',Math.ceil(height)+'px');}
  window.updateGalleryImageLayout=update;
  image?.addEventListener('load',()=>update(state.results[state.selected]));
  if(typeof ResizeObserver==='function'){const observer=new ResizeObserver(syncHeight);observer.observe(main);}
  update(state.results[state.selected]);
  syncHeight();
})();




